<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Database.php';
require dirname(__DIR__).'/app/FinancialService.php';
require dirname(__DIR__).'/app/FinancialState.php';
require dirname(__DIR__).'/app/BusinessState.php';
$c=require dirname(__DIR__).'/config/settings.php';
if($c['environment']!=='local'||!preg_match('/\Acentro_auth_[a-z0-9_]+\z/D',$c['db']['name']))throw new RuntimeException('Synthetic schema required');
$p=Centro\Database::connection($c['db']);
$p->exec("INSERT INTO auth_users(id,email,password_hash,active) VALUES(1,'operations@example.invalid','x',1)");
$p->exec("INSERT INTO environments(id,code,label) VALUES('pruebas','pruebas','Synthetic')");
$p->exec("INSERT INTO currencies(environment_id,id,symbol) VALUES('pruebas','USD','$'),('pruebas','ARS','$')");
$p->exec("INSERT INTO accounts(environment_id,id,name,currency_id) VALUES('pruebas','cash','Cash','USD'),('pruebas','ars','ARS','ARS')");
$p->exec("INSERT INTO customers(environment_id,id,name,country,consent,notes,origin) VALUES('pruebas','customer','Synthetic','AR',1,'','manual')");
$p->exec("INSERT INTO brands(environment_id,id,name,color,dark,alt,description) VALUES('pruebas','brand','Synthetic','#112233','#000000','#ffffff','')");
$p->exec("INSERT INTO projects(environment_id,id,brand_id,name,kind,status,url,description,domain,repo,hosting,database_description,tech,milestone,notes) VALUES('pruebas','project','brand','App','suscripcion','publicada','','','','','','','','','')");
$p->exec("INSERT INTO plans(environment_id,id,project_id,name,status,trial_days) VALUES('pruebas','plan','project','Monthly','activa',7)");
$p->exec("INSERT INTO plan_prices(environment_id,id,plan_id,valid_from,price,currency_id,period,provenance) VALUES('pruebas','price','plan','2020-01-01',10,'USD','mensual','known')");
$s=new Centro\FinancialService($p);$checks=[];
$check=function(string $name,bool $ok)use(&$checks){$checks[]=['check'=>$name,'passed'=>$ok];};
$scalar=function(string $sql)use($p){return $p->query($sql)->fetchColumn();};
$run=fn(string $op,array $cmd)=>$s->execute('pruebas',str_pad($op,16,'x'),1,$cmd);
$reject=function(string $name,string $reason,callable $fn)use($check,$p,$scalar){$before=$scalar('SELECT COUNT(*) FROM fin_operation_receipts');try{$fn();$check($name,false);}catch(Centro\BusinessError $e){$check($name,$e->reason===$reason&&!$p->inTransaction()&&$before===$scalar('SELECT COUNT(*) FROM fin_operation_receipts'));}};
foreach(['capital_contribution'=>'100.00','withdrawal'=>'20.00','treasury_adjustment'=>'5.00'] as $kind=>$amount){$cmd=['kind'=>$kind,'amount'=>$amount,'currency'=>'USD','account_id'=>'cash','date'=>'2026-01-31','confirmed'=>true];$a=$run('op_'.$kind,$cmd);$b=$run('op_'.$kind,$cmd);$check($kind.' exactly once',$a['replayed']===false&&$b['replayed']===true);}
$check('exact treasury balance',$scalar('SELECT SUM(CASE direction WHEN "in" THEN amount ELSE -amount END) FROM fin_movements')==='85.00');
$reject('confirmation required','financial_confirmation_required',fn()=>$run('no_confirmation',['kind'=>'withdrawal','amount'=>'1.00','currency'=>'USD','account_id'=>'cash','date'=>'2026-01-31']));
$reject('currency mismatch','account_currency_mismatch',fn()=>$run('wrong_currency',['kind'=>'withdrawal','amount'=>'1.00','currency'=>'ARS','account_id'=>'cash','date'=>'2026-01-31','confirmed'=>true]));
$reject('idempotency mismatch','idempotency_conflict',fn()=>$run('op_withdrawal',['kind'=>'withdrawal','amount'=>'21.00']));
$base=['subscription_id'=>'sub','plan_id'=>'plan','customer_id'=>'customer','date'=>'2026-01-31','expected_version'=>0,'trial'=>true,'price_snapshot_id'=>'price'];
$r=$run('sub_register',['kind'=>'subscription_register',...$base]);
$check('trial with client/project/plan and expiry',$r['result']['next_renewal']==='2026-02-07'&&$scalar('SELECT COUNT(*) FROM fin_sales')===0);
$reject('missing reference rollback','customer_reference_invalid',fn()=>$run('sub_invalid',['kind'=>'subscription_register',...$base,'subscription_id'=>'bad','customer_id'=>'missing']));
$check('invalid subscription not persisted',$scalar("SELECT COUNT(*) FROM subscriptions WHERE id='bad'")===0);
$renew=['kind'=>'subscription_renew','subscription_id'=>'sub','plan_id'=>'plan','date'=>'2026-02-07','expected_version'=>1,'price_snapshot_id'=>'price','sale_id'=>'first','amount'=>'10.00','currency'=>'USD','settle_now'=>true,'confirmed'=>true,'account_id'=>'cash'];
$r=$run('sub_convert',$renew);$run('sub_convert',$renew);
$check('conversion creates sale and cash once',$scalar('SELECT COUNT(*) FROM fin_sales')===1&&$scalar('SELECT COUNT(*) FROM fin_movements')===4&&$r['result']['status']==='activa');
$reject('stale renewal conflicts','version_conflict',fn()=>$run('stale_renew',[...$renew,'sale_id'=>'stale']));
$reject('failed renewal rolls back status and sale','account_reference_invalid',fn()=>$run('rollback_renew',[...$renew,'date'=>'2026-03-07','expected_version'=>2,'sale_id'=>'rollback','account_id'=>'missing']));
$check('rollback no sale or event',$scalar("SELECT COUNT(*) FROM fin_sales WHERE id='rollback'")===0&&$scalar('SELECT COUNT(*) FROM subscription_events')===2);
$event=fn(string $type,int $v,string $date)=>['kind'=>'subscription_status','subscription_id'=>'sub','plan_id'=>'plan','event'=>$type,'date'=>$date,'expected_version'=>$v,'price_snapshot_id'=>'price'];
$run('pause_sub',$event('pausa',2,'2026-02-08'));
$check('subscription suspended',$scalar('SELECT status FROM subscriptions')==='pausada');
$run('cancel_sub',$event('cancelacion',3,'2026-02-09'));
$reject('cancelled cannot renew','subscription_state_conflict',fn()=>$run('cancelled_renew',[...$renew,'expected_version'=>4,'date'=>'2026-02-10','sale_id'=>'cancelled']));
$run('reactivate_sub',$event('reactivacion',4,'2026-02-10'));
$run('renew_sub',[...$renew,'date'=>'2026-02-10','expected_version'=>5,'sale_id'=>'renewed']);
$check('reactivation renewal and ordered history',$scalar('SELECT COUNT(*) FROM subscription_events')===6&&$scalar('SELECT COUNT(*) FROM fin_subscription_evidence')===6&&$scalar('SELECT row_version FROM subscriptions')===6);
$reject('backdated event rejected','subscription_event_out_of_order',fn()=>$run('backdate',$event('pausa',6,'2026-02-01')));
$reject('missing historical evidence','historical_price_evidence_required',fn()=>$run('wrong_price',[...$event('pausa',6,'2026-02-11'),'price_snapshot_id'=>'missing']));
$run('sale_edit_seed',['kind'=>'sale_register','sale_id'=>'edit','customer_id'=>'customer','currency'=>'USD','amount'=>'10.00','date'=>'2026-01-31','record'=>['concept'=>'Original']]);
$run('sale_edit_cmd',['kind'=>'sale_edit','sale_id'=>'edit','expected_version'=>1,'amount'=>'12.00','customer_id'=>'customer','record'=>['concept'=>'Edited']]);
$run('sale_void_cmd',['kind'=>'sale_void','sale_id'=>'edit','expected_version'=>2]);
$check('sale edit and void retain revision history',$scalar("SELECT COUNT(*) FROM fin_sale_revisions WHERE sale_id='edit'")===2);
$run('expense_seed',['kind'=>'expense_register','expense_id'=>'exp','currency'=>'USD','amount'=>'10.00','date'=>'2026-01-31','record'=>['concept'=>'Rent','nature'=>'gasto']]);
$run('expense_edit',['kind'=>'expense_edit','expense_id'=>'exp','expected_version'=>1,'amount'=>'15.00','record'=>['concept'=>'New rent']]);
$run('expense_pay',['kind'=>'expense_pay','expense_id'=>'exp','expected_version'=>2,'amount'=>'5.00','currency'=>'USD','date'=>'2026-01-31','account_id'=>'cash','confirmed'=>true]);
$reject('expense cannot fall below paid','expense_total_below_paid',fn()=>$run('expense_bad',['kind'=>'expense_edit','expense_id'=>'exp','expected_version'=>3,'amount'=>'4.00']));
$state=new Centro\FinancialState($p);$snapshot=$state->snapshot('pruebas');
$check('projection preserves metadata and SQL versions',count(array_filter($snapshot['expenses'],fn($x)=>$x['concept']==='New rent'&&$x['_sqlPaid']==='5.00'&&$x['_sqlVersion']===3))===1);
$bs=new Centro\BusinessState($p);$bs->save('pruebas','state_12345678901234567890',1,['version'=>1,'sales'=>[['id'=>'forged','unitPrice'=>999999]],'subs'=>[],'treasury'=>[]],0);
$check('business_state cannot overwrite financial tables',$state->snapshot('pruebas')===$snapshot);
$reject('unsupported commissions are not silently reinterpreted','unsupported_financial_adjustments',fn()=>$run('unsafe_commission',['kind'=>'sale_register','sale_id'=>'unsafe','amount'=>'10.00','currency'=>'USD','date'=>'2026-01-31','commission'=>'1.00']));
$check('one audit per receipt',$scalar('SELECT COUNT(*) FROM fin_audit')===$scalar('SELECT COUNT(*) FROM fin_operation_receipts'));
$check('each event is linked to a financial operation',$scalar('SELECT COUNT(*) FROM fin_subscription_evidence x LEFT JOIN fin_operation_receipts o ON o.environment_id=x.environment_id AND o.operation_id=x.operation_id WHERE o.operation_id IS NULL')===0);
$check('balance after renewals and expense payment',$scalar('SELECT SUM(CASE direction WHEN "in" THEN amount ELSE -amount END) FROM fin_movements')==='100.00');
echo json_encode(['checks'=>$checks,'passed'=>count(array_filter($checks,fn($x)=>$x['passed'])),'total'=>count($checks)],JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT).PHP_EOL;
exit(array_filter($checks,fn($x)=>!$x['passed'])?1:0);
